//! Explicitly forgetting a disabled source never removes audio files.
use anyhow::{ensure,Context,Result};use serde::{Serialize,Deserialize};use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::path::Path;use musicos_init::database::Connection;
#[derive(Serialize,Deserialize,Clone)]pub struct Preview{pub id:i64,pub name:String,pub path:String,pub songs:usize,pub favorites:usize,pub memberships:usize,pub metadata:usize,pub token:String,pub track_ids:Vec<i64>,pub revisions:Vec<(i64,i64)>}
fn digest(value:&impl Serialize)->Result<String>{Ok(format!("{:x}",Sha256::digest(serde_json::to_vec(value)?)))}
pub fn preview(database:&Path,id:i64,managed:&Path)->Result<Preview>{let db=Connection::open(database)?;let (name,path,enabled,kind):(String,String,bool,String)=db.query_row("SELECT display_name,path,enabled,kind FROM library_sources WHERE id=?",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?)))?;
 let tracks=db.prepare("SELECT id,revision,favorited FROM tracks WHERE source_id=? ORDER BY id")?.query_map([id],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,i64>(1)?,r.get::<_,bool>(2)?)))?.collect::<rusqlite::Result<Vec<_>>>()?;
 let same=Path::new(&path).canonicalize().ok().zip(managed.canonicalize().ok()).is_some_and(|(a,b)|a==b)||Path::new(&path)==managed;
 ensure!(!same,"The configured musicOS library cannot be forgotten");ensure!(!enabled||(kind=="managed"&&tracks.is_empty()),"Remove this folder from the library first");ensure!(kind!="managed"||tracks.is_empty(),"Only empty legacy musicOS sources can be forgotten");
 let ids=tracks.iter().map(|t|t.0).collect::<Vec<_>>();let ids_json=serde_json::to_string(&ids)?;let memberships_detail=db.prepare("SELECT playlist_id,track_id,position FROM playlist_tracks WHERE track_id IN (SELECT value FROM json_each(?)) ORDER BY playlist_id,track_id")?.query_map([&ids_json],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,i64>(1)?,r.get::<_,i64>(2)?)))?.collect::<rusqlite::Result<Vec<_>>>()?;let memberships:i64=db.query_row("SELECT count(*) FROM playlist_tracks WHERE track_id IN (SELECT value FROM json_each(?))",[&ids_json],|r|r.get(0))?;let audio=crate::audio_collections::list(database)?;let audio_members=audio.iter().map(|a|a.track_ids.iter().filter(|id|ids.contains(id)).count()).sum::<usize>();
 let metadata:i64=db.query_row("SELECT count(*) FROM track_metadata_overrides WHERE track_id IN (SELECT value FROM json_each(?))",[&ids_json],|r|r.get(0))?;let token=digest(&(id,&name,&path,enabled,kind,&tracks,&memberships_detail,&audio))?;Ok(Preview{id,name,path,songs:ids.len(),favorites:tracks.iter().filter(|t|t.2).count(),memberships:memberships as usize+audio_members,metadata:metadata as usize,token,revisions:tracks.iter().map(|t|(t.0,t.1)).collect(),track_ids:ids})}
pub fn apply(database:&Path,id:i64,managed:&Path,token:&str,queued:&[i64])->Result<usize>{let guard=Connection::open(database)?;let _writer=guard.reserve_writer()?;let plan=preview(database,id,managed)?;ensure!(plan.token==token,"This folder changed. Review it again.");ensure!(!queued.iter().any(|id|plan.track_ids.contains(id)),"Remove this folder’s songs from Up next before forgetting it");
 let db=Connection::open(database)?;let audio_before=crate::audio_collections::list(database)?;let mut audio=audio_before.clone();for item in &mut audio{item.track_ids.retain(|id|!plan.track_ids.contains(id));}let audio_path=crate::audio_collections::path(database);
 let recovery=database.with_extension("forget-recovery.json");musicos_desktop::storage::atomic_write_json(&recovery,&json!({"source":id,"token":token,"audio_before":audio_before}))?;
 musicos_desktop::storage::atomic_write_json(&audio_path,&audio)?;
 let result=(||->Result<()>{let tx=db.unchecked_transaction()?;let current_source:(String,String)=tx.query_row("SELECT display_name,path FROM library_sources WHERE id=? AND (enabled=0 OR kind='managed')",[id],|r|Ok((r.get(0)?,r.get(1)?)))?;ensure!(current_source==(plan.name.clone(),plan.path.clone()),"Folder changed. Review again");let current:i64=tx.query_row("SELECT count(*) FROM tracks WHERE source_id=?",[id],|r|r.get(0))?;ensure!(current as usize==plan.songs,"Folder changed. Review again");let revisions=tx.prepare("SELECT id,revision FROM tracks WHERE source_id=? ORDER BY id")?.query_map([id],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,i64>(1)?)))?.collect::<rusqlite::Result<Vec<_>>>()?;ensure!(revisions==plan.revisions,"Folder changed. Review again");let ids=serde_json::to_string(&plan.track_ids)?;
 let tables=tx.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")?.query_map([],|r|r.get::<_,String>(0))?.collect::<rusqlite::Result<Vec<_>>>()?;
 for table in tables{ensure!(table.chars().all(|c|c.is_ascii_alphanumeric()||c=='_'),"Invalid database table name");let columns=tx.prepare(&format!("PRAGMA table_info({table})"))?.query_map([],|r|r.get::<_,String>(1))?.collect::<rusqlite::Result<Vec<_>>>()?;if columns.iter().any(|c|c=="track_id"){tx.execute(&format!("DELETE FROM {table} WHERE track_id IN (SELECT value FROM json_each(?))"),[&ids])?;}}
 if tx.query_row("SELECT count(*) FROM sqlite_master WHERE name='desktop_metadata_changes_v1'",[],|r|r.get::<_,i64>(0))?>0{tx.execute("DELETE FROM desktop_metadata_changes_v1 WHERE id NOT IN (SELECT change_id FROM desktop_metadata_change_entries_v1)",[])?;}
 tx.execute("DELETE FROM pins WHERE pin_type='track' AND target_id IN (SELECT value FROM json_each(?))",[&ids])?;tx.execute("DELETE FROM tracks WHERE source_id=?",[id])?;ensure!(tx.execute("DELETE FROM library_sources WHERE id=?",[id])?==1,"Folder no longer exists");tx.commit()?;Ok(())})();
 if let Err(error)=result{musicos_desktop::storage::atomic_write_json(&audio_path,&audio_before)?;let _=std::fs::remove_file(recovery);return Err(error);}std::fs::remove_file(recovery)?;Ok(plan.songs)}
pub fn recover(database:&Path)->Result<()>{let path=database.with_extension("forget-recovery.json");if !path.exists(){return Ok(());}let value:Value=serde_json::from_slice(&std::fs::read(&path)?)?;let id=value["source"].as_i64().context("Invalid source recovery")?;let db=Connection::open(database)?;let exists:i64=db.query_row("SELECT count(*) FROM library_sources WHERE id=?",[id],|r|r.get(0))?;if exists>0{musicos_desktop::storage::atomic_write_json(&crate::audio_collections::path(database),&value["audio_before"])?;}std::fs::remove_file(path)?;Ok(())}
#[cfg(test)]mod tests{use super::*;use musicos_init::database::Db;
 #[test]fn forget_removes_only_owned_records_and_blocks_stale_or_queued_plans(){let temp=tempfile::tempdir().unwrap();let path=temp.path().join("db");let original=temp.path().join("one.flac");std::fs::write(&original,b"original").unwrap();let db=Db::open(&path.to_string_lossy()).unwrap();let source=db.add_library_source("reference",temp.path().to_str().unwrap(),"Removed").unwrap();let other=db.add_library_source("reference",temp.path().join("nested").to_str().unwrap(),"Other").unwrap();let id=db.insert_track(original.to_str().unwrap(),"One","Artist","Album",1,2,8).unwrap();db.assign_track_source(id,source.id).unwrap();let keep=db.insert_track("/other.flac","Keep","Artist","Album",1,2,8).unwrap();db.assign_track_source(keep,other.id).unwrap();db.toggle_favorite(id).unwrap();let playlist=db.create_playlist("Keep collection").unwrap();db.add_tracks_to_playlist(playlist,&[id,keep]).unwrap();db.update_library_source(source.id,None,Some(false)).unwrap();let managed=temp.path().join("managed");let plan=preview(&path,source.id,&managed).unwrap();assert_eq!((plan.songs,plan.favorites,plan.memberships),(1,1,1));assert!(apply(&path,source.id,&managed,&plan.token,&[id]).is_err());db.update_track_metadata_override(&[id],&musicos_init::database::MetadataUpdate{title:Some("Later".into()),..Default::default()}).unwrap();assert!(apply(&path,source.id,&managed,&plan.token,&[]).is_err());let plan=preview(&path,source.id,&managed).unwrap();assert_eq!(apply(&path,source.id,&managed,&plan.token,&[]).unwrap(),1);assert!(db.get_track_by_id(id).unwrap().is_none());assert!(db.get_track_by_id(keep).unwrap().is_some());assert_eq!(db.playlist_track_count(playlist).unwrap(),1);assert_eq!(std::fs::read(original).unwrap(),b"original");assert!(db.library_source(other.id).unwrap().is_some());}
}
